using System.Collections.Generic;

namespace SDRLink
{
    // Traductions (texte anglais -> langue). Fichier généré par tools\langgen.ps1 à partir de lang\*.txt : ne pas modifier à la main.
    static class LangData
    {
        public static Dictionary<string, string> Load(string code)
        {
            string[] p;
            switch (code)
            {
                case "bg": p = BG; break;
                case "cs": p = CS; break;
                case "da": p = DA; break;
                case "de": p = DE; break;
                case "el": p = EL; break;
                case "es": p = ES; break;
                case "et": p = ET; break;
                case "fi": p = FI; break;
                case "hr": p = HR; break;
                case "hu": p = HU; break;
                case "it": p = IT; break;
                case "lt": p = LT; break;
                case "lv": p = LV; break;
                case "nb": p = NB; break;
                case "nl": p = NL; break;
                case "pl": p = PL; break;
                case "pt": p = PT; break;
                case "ro": p = RO; break;
                case "sk": p = SK; break;
                case "sl": p = SL; break;
                case "sv": p = SV; break;
                default: return new Dictionary<string, string>();
            }
            Dictionary<string, string> d = new Dictionary<string, string>(p.Length / 2);
            for (int i = 0; i + 1 < p.Length; i += 2) d[p[i]] = p[i + 1];
            return d;
        }
